#!/bin/bash
# Run from inside ~/itx_ace_app
python3 -c "
import base64, os

app = ''
proxy = ''

os.makedirs('api', exist_ok=True)

with open('src/App.jsx', 'wb') as f:
    f.write(base64.b64decode(app.replace('\n','').replace(' ','')))
print('src/App.jsx updated')

with open('api/claude.js', 'wb') as f:
    f.write(base64.b64decode(proxy.replace('\n','').replace(' ','')))
print('api/claude.js created')
"
